 ***/
export function normalizeRecord(entry) {
	if (!entry || typeof entry !== "object") {
		return makeLogRecord({ kind: "system", text: "" });
	}
	return makeLogRecord({
		...entry,
		feeds: Array.isArray(entry.feeds) ? entry.feeds : undefined,
		feed: entry.feed,
	});
}

